"""Patch the AndroidManifest.xml generated by `flutter create`.

- network permissions (the release build has none by default; mDNS needs multicast)
- plain HTTP to the box on the local network
- app name "SyncLight"
"""

import re
import sys

PERMISSIONS = [
    "android.permission.INTERNET",
    "android.permission.ACCESS_NETWORK_STATE",
    "android.permission.ACCESS_WIFI_STATE",
    "android.permission.CHANGE_WIFI_MULTICAST_STATE",
]

path = sys.argv[1]
with open(path, encoding="utf-8") as fh:
    xml = fh.read()

perm_lines = "".join(
    f'\n    <uses-permission android:name="{p}"/>' for p in PERMISSIONS if p not in xml
)
xml = re.sub(r"(<manifest\b[^>]*>)", lambda m: m.group(1) + perm_lines, xml, count=1)

def fix_application(match):
    tag = match.group(0)
    tag = re.sub(r'\s*android:usesCleartextTraffic="[^"]*"', "", tag)
    tag = re.sub(r'android:label="[^"]*"', 'android:label="SyncLight"', tag)
    return tag.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)

xml, n = re.subn(r"<application\b[^>]*>", fix_application, xml, count=1)
if n != 1:
    sys.exit("could not find <application> in " + path)

with open(path, "w", encoding="utf-8") as fh:
    fh.write(xml)
print("Patched", path)
